"use strict";(()=>{function t(e){return typeof window<"u"&&window.__rvLesson&&window.__rvLesson(e),e}var i={asm:"add x5, x6, x7",regs:{6:23,7:19}},r={asm:"sw x7, 12(x6)",regs:{6:4096,7:305419896}},s={asm:"beq x5, x6, +16",pc:16,regs:{5:7,6:7}},n={asm:"srai x5, x6, 4",regs:{6:-256}},l=t({id:10,title:"The control unit",short:"Control unit",goal:"Derive the main decoder, the ALU decoder and the gate-level logic.",level:10,scope:["add","sub","and","or","xor","slt","sltu","sll","srl","sra","addi","andi","ori","xori","slti","sltiu","slli","srli","srai","lw","lb","lh","lbu","lhu","sw","sb","sh","beq","bne","blt","bge","bltu","bgeu","jal","jalr","lui","auipc"],tool:"control",steps:[{title:"Where do the control signals come from?",text:"Every orange stub so far showed a value we simply read off. Eleven signals steer the datapath. Now we build the block that produces them.",panel:"ctrl-signals",noDiagram:!0},{title:"The control unit",text:"The control unit sits above the register file. Its inputs are only three instruction fields: {opcode} (bits 6:0), {funct3} (14:12) and bit 30 of {funct7}. It never needs rs1, rs2 or rd: those go straight to the datapath.",reveal:["cu"],example:i,fields:["opcode","funct3","funct7"],flow:["stage:pc","stage:fetch","w_spine","w_spine_cu","w_op","w_f3","w_b30"],focus:["ctrl"],camera:"follow"},{title:"Outputs are named stubs",text:"Each output carries a label. A stub with the same name at a block is the same net, which keeps the drawing readable: eleven long wires would cross most of the datapath. For add: RegWrite = 1, ALUSrc = 0, ALUControl = add, ResultSrc = 00.",flow:["ctrl","stage:ctrl"],camera:"follow"},{title:"Main decoder: one row per opcode",text:"Nine instruction classes have nine different opcodes, and almost every signal depends only on the opcode. So the main decoder is a truth table with nine rows. Every row follows from what you built in Lessons 1 to 9.",panel:"main-table",noDiagram:!0},{title:"Don't-cares",text:"An x means the signal cannot affect the result for that class. A store writes no register, so ResultSrc is x; jal does not use the ALU, so ALUSrc and ALUOp are x. The designer may choose either value, which makes the logic smaller.",panel:"main-table",noDiagram:!0,predict:{q:"For `beq`, which of these is a don't-care?",options:[{label:"ResultSrc",value:"ResultSrc"},{label:"ALUSrc",value:"ALUSrc"},{label:"PCTargetSrc",value:"PCTargetSrc"},{label:"RegWrite",value:"RegWrite"}],answer:()=>"ResultSrc",explain:()=>"beq writes no register (RegWrite = 0), so whatever the result mux passes is discarded. ALUSrc must be 0 for the compare, PCTargetSrc must be 0 for a PC-relative target, and RegWrite must be 0.",concept:"main-decoder"}},{title:"The ALU decoder",text:"Rather than decode funct3 in the main decoder, it outputs a 2-bit class ALUOp: 00 add, 01 subtract, 10 R-type, 11 I-type. A small ALU decoder combines ALUOp with funct3 and bit 30. This split keeps both decoders small.",panel:"alu-table",example:n,noDiagram:!0,fields:["funct3","funct7"]},{title:"From the table to gates",text:"Opcode bits 1:0 are always 11, so each signal is a function of bits 6:2 only. With the don't-cares, most signals need one or two AND terms. MemWrite, for example, is \xACb6\xB7b5\xB7\xACb4: only the store opcode 01000 matches.",panel:"gates",example:r,noDiagram:!0},{text:"For sw the control unit outputs MemWrite = 1, RegWrite = 0, ALUSrc = 1, ImmSrc = S.",example:r,flow:["stage:pc","stage:fetch","w_spine","w_spine_cu","w_op","w_f3","w_b30","ctrl","stage:ctrl"],camera:"follow",predict:{q:"Which signal stops `sw` from changing any register?",options:[{label:"RegWrite = 0",value:"RegWrite"},{label:"MemRead = 0",value:"MemRead"},{label:"ResultSrc = 00",value:"ResultSrc"},{label:"ImmSrc = S",value:"ImmSrc"}],answer:()=>"RegWrite",explain:()=>"RegWrite is the register file's write enable. With it at 0, whatever reaches WD3 is ignored at the clock edge.",concept:"main-decoder"}},{title:"Branches",text:"For beq: Branch = 1, ALUOp = 01 (subtract), ImmSrc = B, ALUSrc = 0, RegWrite = 0, MemWrite = 0. Whether the PC actually changes is decided later in the cycle by the branch condition, not by the control unit.",example:s,flow:["stage:pc","stage:fetch","w_spine","w_spine_cu","w_op","w_f3","w_b30","ctrl","stage:ctrl"],camera:"follow"},{title:"Your turn",text:"Open the Control unit lab: fill in the main decoder table and the ALU decoder yourself, then click any opcode to watch each gate term and each control signal fire.",panel:"gates",noDiagram:!0}],practice:[{kind:"control",ops:["add","addi","lw","sw","beq","jal","jalr","lui","auipc","srai","bltu","lbu"],title:"Set the control signals for any instruction"},{kind:"break",title:"Break the control unit",faults:["stuck:RegWrite:1","stuck:ALUSrc:0","stuck:MemWrite:0","stuck:ResultSrc:0","stuck:Jump:1"]},{kind:"design",challenge:"lui",title:"Design challenges: add a new instruction"},{kind:"quiz",title:"Control unit check",concepts:["main-decoder","alu-decoder","alusrc","resultsrc","store-regwrite"]}]});})();
